 PROCEDURE release_request(p_lock IN OUT PLS_INTEGER) IS ignored PLS_INTEGER;BEGIN
   IF p_lock IS NOT NULL THEN ignored:=DBMS_LOCK.RELEASE(p_lock);p_lock:=NULL;END IF;
