   c:=SUBSTR(p_text,i,1);
   IF c=CHR(39) THEN
    r:=r||c;
    IF quoted AND SUBSTR(p_text,'');
 l_sql:=l_sql||TO_CLOB(''i+1,1)=CHR(39) THEN r:=r||CHR(39);i:=i+1;
    ELSE quoted:=NOT quoted; END IF;
   ELSIF quoted THEN r:=r||c;
   ELSIF c NOT IN ('''' '''',CHR(9),CHR(10),CHR(13),''''"'''') THEN r:=r||UPPER(c);
   END IF;
   i:=i+1;
  END LOOP;
